import { defineConfig } from '@playwright/test'

/**
 * The load benches of the project format (QA-7, #130): measurements, not tests. They are run by
 * hand, on a reference machine, with `pnpm bench:project`; they are not part of `pnpm test:e2e`
 * and never run in CI. The folder they measure is generated by the native bench
 * (`crates/project/benches/load`, docs/spikes/QA-7-banc-de-charge-format-projet.md). Each spec
 * serves what it needs from a loopback server of its own: no dev server.
 */
export default defineConfig({
  testDir: 'tests/bench',
  testMatch: '*.bench.ts',
  workers: 1,
  fullyParallel: false,
  retries: 0,
  timeout: 30 * 60_000,
  reporter: 'list',
  // `FAULK_BENCH_JSFLAGS` is handed to V8 (e.g. `--no-wasm-lazy-compilation`, to tell a first-call cost from a steady one, #283).
  use: {
    channel: process.env.FAULK_E2E_CHANNEL || undefined,
    locale: 'en-US',
    launchOptions: { args: process.env.FAULK_BENCH_JSFLAGS ? [`--js-flags=${process.env.FAULK_BENCH_JSFLAGS}`] : [] },
  },
})
